/* TEMPORARY regression probe — Stage 3. Deleted immediately after running. */
import { describe, expect, test } from 'vitest';
import theme from '../index';
import { components } from './index';
import baseTheme from '@salesforce/retail-react-app/app/theme';
import { spacing } from '../foundation/spacing';
import { fontSizes, letterSpacings, lineHeights } from '../foundation/typography';
import { breakpoints } from '../foundation/gridSystem';

const SPACING_KEYS = new Set(Object.keys(spacing));
const BP = new Set(Object.keys(breakpoints));
const SIZING = new Set(['width','height','minWidth','minHeight','maxWidth','maxHeight','w','h','minW','minH','maxW','maxH','boxSize','flexBasis','basis','top','right','bottom','left','blockSize','inlineSize']);
const TYPO: Record<string, Set<string>> = {
  fontSize: new Set([...Object.keys(fontSizes), ...SPACING_KEYS]),
  lineHeight: new Set([...Object.keys(lineHeights), ...SPACING_KEYS]),
  letterSpacing: new Set([...Object.keys(letterSpacings), ...SPACING_KEYS]),
};

const isResp = (n: object) => Array.isArray(n) || (Object.keys(n).length > 0 && Object.keys(n).every((k) => BP.has(k)));

type Hit = { recipe: string; path: string; prop: string; value: string };
const walk = (node: unknown, recipe: string, path: string, prop: string, out: Hit[]): void => {
  if (node === null || typeof node !== 'object') return;
  const resp = isResp(node);
  for (const [k, v] of Object.entries(node as Record<string, unknown>)) {
    const here = path ? `${path}.${k}` : k;
    const p = resp ? prop : k;
    if (v !== null && typeof v === 'object') walk(v, recipe, here, p, out);
    else if (typeof v === 'string') out.push({ recipe, path: here, prop: p, value: v });
  }
};

const resolveBase = (r: Record<string, unknown>): unknown => {
  const bs = r.baseStyle;
  if (typeof bs !== 'function') return bs;
  const merged: Record<string, unknown> = {};
  for (const props of [{}, { variant: 'inverse' }, { variant: 'light' }, { variant: 'default' }, { inverse: true }, { inverse: false }]) {
    try { Object.assign(merged, (bs as (p: unknown) => object)(props)); } catch { /* ignore */ }
  }
  return merged;
};

const collectFrom = (map: Record<string, unknown>): Hit[] => {
  const out: Hit[] = [];
  for (const [name, recipe] of Object.entries(map)) {
    if (!recipe || typeof recipe !== 'object') continue;
    const r = recipe as Record<string, unknown>;
    for (const s of [resolveBase(r), r.variants, r.sizes]) walk(s, name, '', '', out);
  }
  return out;
};

describe('PROBE', () => {
  test('A: independent bare-key sweep over OUR components map', () => {
    const hits = collectFrom(components as unknown as Record<string, unknown>);
    const sizing = hits.filter((f) => SIZING.has(f.prop) && SPACING_KEYS.has(f.value));
    const typo = hits.filter((f) => TYPO[f.prop]?.has(f.value));
    const compound = hits.filter((f) => {
      if (!SPACING_KEYS.has(f.value) && /\s/.test(f.value)) {
        const parts = f.value.replace(/var\([^)]*\)/g, 'VAR').split(/\s+/);
        return parts.some((p) => SPACING_KEYS.has(p));
      }
      return false;
    });
    console.log('PROBE_A total_leaves=' + hits.length);
    console.log('PROBE_A sizing_offenders=' + JSON.stringify(sizing));
    console.log('PROBE_A typo_offenders=' + JSON.stringify(typo));
    console.log('PROBE_A compound_offenders=' + JSON.stringify(compound));
    expect(sizing).toEqual([]); expect(typo).toEqual([]); expect(compound).toEqual([]);
  });

  test('B: same sweep over the COMPOSED theme (includes deep-merged SFCC base)', () => {
    const hits = collectFrom(theme.components as unknown as Record<string, unknown>);
    const ours = new Set(Object.keys(components));
    const sizing = hits.filter((f) => SIZING.has(f.prop) && SPACING_KEYS.has(f.value));
    const typo = hits.filter((f) => TYPO[f.prop]?.has(f.value));
    console.log('PROBE_B composed_recipes=' + Object.keys(theme.components).length + ' total_leaves=' + hits.length);
    console.log('PROBE_B sizing_in_OUR_recipes=' + JSON.stringify(sizing.filter((f) => ours.has(f.recipe))));
    console.log('PROBE_B typo_in_OUR_recipes=' + JSON.stringify(typo.filter((f) => ours.has(f.recipe))));
    console.log('PROBE_B sizing_in_BASE_recipes_count=' + sizing.filter((f) => !ours.has(f.recipe)).length);
    console.log('PROBE_B typo_in_BASE_recipes_count=' + typo.filter((f) => !ours.has(f.recipe)).length);
  });

  test('C: ZimmLogo collision + registration', () => {
    const baseKeys = Object.keys((baseTheme as { components: Record<string, unknown> }).components);
    console.log('PROBE_C base_recipe_count=' + baseKeys.length);
    console.log('PROBE_C ours=' + JSON.stringify(Object.keys(components)));
    const collisions = Object.keys(components).filter((k) => baseKeys.includes(k));
    console.log('PROBE_C collisions=' + JSON.stringify(collisions));
    console.log('PROBE_C ZimmLogo_in_base=' + baseKeys.includes('ZimmLogo'));
    console.log('PROBE_C ZimmLogo_composed=' + JSON.stringify((theme.components as Record<string, unknown>).ZimmLogo));
  });

  test('D: parts vs styled-part parity (function baseStyles resolved)', () => {
    for (const [name, recipe] of Object.entries(components as unknown as Record<string, Record<string, unknown>>)) {
      const parts = (recipe.parts as string[] | undefined) ?? null;
      const bs = resolveBase(recipe);
      const styled = bs && typeof bs === 'object' ? Object.keys(bs as object) : [];
      if (!parts) { console.log(`PROBE_D ${name}: single-part recipe, baseStyle keys=${styled.length}`); continue; }
      const missing = parts.filter((p) => !styled.includes(p));
      const extra = styled.filter((p) => !parts.includes(p));
      console.log(`PROBE_D ${name}: parts=${parts.length} styled=${styled.length} missing=${JSON.stringify(missing)} extra=${JSON.stringify(extra)}`);
    }
  });
});
