import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright/index.mjs';

const SB = 'http://127.0.0.1:6099/iframe.html?id=';
const out = (k, v) => console.log(`${k}\t${typeof v === 'object' ? JSON.stringify(v) : v}`);

const SEL = {
  footer: 'footer[role="contentinfo"]',
  main: 'footer[role="contentinfo"] > div:nth-child(1)',
  contentRow: 'footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1)',
  subscribe: 'footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1) > div:nth-child(1)',
  links: 'footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1) > div:nth-child(2)',
  logoArea: 'footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(2)',
  bottomBar: 'footer[role="contentinfo"] > div:nth-child(2)',
};

const rect = (page, sel) => page.evaluate((s) => {
  const e = document.querySelector(s); if (!e) return null;
  const r = e.getBoundingClientRect();
  return { w: +r.width.toFixed(2), h: +r.height.toFixed(2), x: +r.x.toFixed(2), y: +r.y.toFixed(2) };
}, sel);

const browser = await chromium.launch();

// ─────────────── PART 1: footer layout baselines @1440 ───────────────
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 1200 } });
  await page.goto(SB + 'layout-footer--default', { waitUntil: 'networkidle' });
  await page.waitForSelector(SEL.footer);
  await page.waitForTimeout(600);
  for (const [k, s] of Object.entries(SEL)) out(`P1_1440_${k}`, await rect(page, s));
  // link column geometry
  out('P1_1440_linkCols', await page.evaluate(() => [...document.querySelectorAll('footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1) > div:nth-child(2) > div > div')].map((e) => { const r = e.getBoundingClientRect(); return { w: +r.width.toFixed(2), h: +r.height.toFixed(2) }; })));
  await page.close();
}

// ─────────────── PART 2: S10 baselines @1440 and @390 ───────────────
for (const vw of [1440, 390]) {
  const page = await browser.newPage({ viewport: { width: vw, height: 1400 } });
  await page.goto(SB + 'layout-footer--default', { waitUntil: 'networkidle' });
  await page.waitForSelector(SEL.footer);
  await page.waitForTimeout(600);
  const data = await page.evaluate(() => {
    const cols = [...document.querySelectorAll('footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1) > div:nth-child(2) > div > div')];
    return cols.map((col) => {
      const heading = col.querySelector('p');
      const lis = [...col.querySelectorAll('li')];
      return {
        heading: heading?.textContent,
        headingPL: getComputedStyle(heading).paddingLeft,
        items: lis.map((li) => {
          const a = li.querySelector('a');
          const lr = li.getBoundingClientRect();
          const ar = a?.getBoundingClientRect();
          return {
            label: (a?.textContent ?? '[icon-row]').trim().slice(0, 34),
            liPL: getComputedStyle(li).paddingLeft,
