    const r = {};
    for (const [k, s] of Object.entries(SEL)) r[k] = await rect(page, s);
    r.slot = await page.evaluate(() => {
      const c = document.querySelector('footer[role="contentinfo"] [aria-live="polite"]');
      if (!c) return null; const b = c.getBoundingClientRect();
      return { w: +b.width.toFixed(2), h: +b.height.toFixed(2) };
    });
    return r;
  };
  const before = await snap();
  const email = page.locator('footer[role="contentinfo"] input[type="email"], footer[role="contentinfo"] input').first();
  const n = await email.count();
  let submitted = false, errText = null, errStyle = null;
  if (n > 0) {
    await email.fill('not-an-email');
    const btn = page.locator('footer[role="contentinfo"] button[type="submit"]').first();
    if (await btn.count()) { await btn.click({ force: true }); submitted = true; }
    else { await email.press('Enter'); submitted = true; }
    await page.waitForTimeout(700);
    errStyle = await page.evaluate(() => {
      const sc = document.querySelector('footer[role="contentinfo"] [aria-live="polite"]');
      const cands = [...(sc ?? document).querySelectorAll('div,p,span')].filter((e) => e.children.length === 0 && e.textContent.trim().length > 4);
      // prefer an element whose computed colour is the error colour
      const pick = cands.find((e) => /valid|email|enter|error/i.test(e.textContent)) ?? null;
      if (!pick) return null;
      const cs = getComputedStyle(pick); const r = pick.getBoundingClientRect();
      return { text: pick.textContent.trim(), fontFamily: cs.fontFamily, fontSize: cs.fontSize, fontWeight: cs.fontWeight, lineHeight: cs.lineHeight, letterSpacing: cs.letterSpacing, fontStyle: cs.fontStyle, color: cs.color, marginTop: cs.marginTop, box: { w: +r.width.toFixed(2), h: +r.height.toFixed(2) } };
    });
    errText = errStyle?.text ?? null;
  }
  const after = await snap();
  const delta = {};
  for (const k of Object.keys(before)) {
    if (!before[k] || !after[k]) { delta[k] = 'MISSING'; continue; }
    delta[k] = { dw: +(after[k].w - before[k].w).toFixed(2), dh: +(after[k].h - before[k].h).toFixed(2) };
  }
  out(`P4_${vw}_inputFound`, n);
  out(`P4_${vw}_submitted`, submitted);
  out(`P4_${vw}_before`, before);
  out(`P4_${vw}_after`, after);
  out(`P4_${vw}_DELTA`, delta);
  out(`P4_${vw}_err`, errStyle);
  await page.close();
}

await browser.close();
