import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright/index.mjs';
const out = (k, v) => console.log(`${k}\t${typeof v === 'object' ? JSON.stringify(v) : v}`);
const SEL = {
  footer: 'footer[role="contentinfo"]',
  main: 'footer[role="contentinfo"] > div:nth-child(1)',
  contentRow: 'footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1)',
  subscribe: 'footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1) > div:nth-child(1)',
  links: 'footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1) > div:nth-child(2)',
  logoArea: 'footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(2)',
  bottomBar: 'footer[role="contentinfo"] > div:nth-child(2)',
};
const snap = (page) => page.evaluate((SEL) => {
  const r = {};
  for (const [k, s] of Object.entries(SEL)) {
    const e = document.querySelector(s);
    r[k] = e ? +e.getBoundingClientRect().height.toFixed(3) : null;
  }
  const sc = document.querySelector('footer[role="contentinfo"] [aria-live="polite"]');
  r.slot = sc ? +sc.getBoundingClientRect().height.toFixed(3) : null;
  const inp = document.querySelector('footer[role="contentinfo"] input');
  r.field = inp ? +inp.closest('div').getBoundingClientRect().height.toFixed(3) : null;
  r.inputH = inp ? +inp.getBoundingClientRect().height.toFixed(3) : null;
  return r;
}, SEL);

const browser = await chromium.launch();

// ─── A: real dev-server page @1440 ───
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 1200 } });
  try {
    await page.goto('http://localhost:3000/', { waitUntil: 'domcontentloaded', timeout: 60000 });
    await page.waitForSelector(SEL.footer, { timeout: 45000 });
    await page.waitForTimeout(2500);
    out('A_devserver_1440', await snap(page));
    out('A_devserver_linkCols', await page.evaluate(() => [...document.querySelectorAll('footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1) > div:nth-child(2) > div > div')].map((e) => +e.getBoundingClientRect().height.toFixed(3))));
    out('A_devserver_subscribeChildren', await page.evaluate(() => [...document.querySelector('footer[role="contentinfo"] > div:nth-child(1) > div:nth-child(1) > div:nth-child(1)').children].map((e) => ({ tag: e.tagName, h: +e.getBoundingClientRect().height.toFixed(3) }))));
  } catch (e) { out('A_devserver_ERROR', String(e).slice(0, 200)); }
  await page.close();
}

// ─── B: VALID email submit → is the slot Δ0? ───
for (const vw of [1440, 768, 375, 320]) {
  const page = await browser.newPage({ viewport: { width: vw, height: 1400 } });
  await page.goto('http://127.0.0.1:6099/iframe.html?id=layout-footer--default', { waitUntil: 'networkidle' });
  await page.waitForSelector(SEL.footer); await page.waitForTimeout(600);
  const before = await snap(page);
  const email = page.locator('footer[role="contentinfo"] input').first();
  await email.fill('valid.person@example.com');
  const btn = page.locator('footer[role="contentinfo"] button[type="submit"]').first();
  if (await btn.count()) await btn.click({ force: true }); else await email.press('Enter');
  await page.waitForTimeout(1200);
  const after = await snap(page);
  const d = {}; for (const k of Object.keys(before)) d[k] = (after[k] === null || before[k] === null) ? `${before[k]}->${after[k]}` : +(after[k] - before[k]).toFixed(3);
  out(`B_${vw}_before`, before); out(`B_${vw}_after`, after); out(`B_${vw}_DELTA`, d);
  out(`B_${vw}_endState`, await page.evaluate(() => { const sc = document.querySelector('footer[role="contentinfo"] [aria-live="polite"]'); return sc ? sc.textContent.trim().slice(0, 90) : null; }));
  await page.close();
}

// ─── C: 200% root font-size — does the rem derivation hold (the whole point of S11)? ───
for (const pct of [100, 200]) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 1400 } });
  await page.goto('http://127.0.0.1:6099/iframe.html?id=layout-footer--default', { waitUntil: 'networkidle' });
  await page.waitForSelector(SEL.footer);
  await page.evaluate((p) => { document.documentElement.style.fontSize = `${16 * (p / 100)}px`; }, pct);
  await page.waitForTimeout(800);
  const s = await snap(page);
  out(`C_root${pct}`, { slot: s.slot, field: s.field, inputH: s.inputH, over: +(s.slot - s.field).toFixed(3) });
  await page.close();
}

await browser.close();
